CREATE OR REPLACE FUNCTION public.enforce_action_approval_floor() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.authority_level='commit' THEN NEW.required_approver_count := greatest(NEW.required_approver_count,2); ELSIF NEW.authority_level='act' THEN NEW.required_approver_count := greatest(NEW.required_approver_count,1); END IF; IF NEW.approval_status='approved' AND (TG_OP='INSERT' OR OLD.approval_status IS DISTINCT FROM NEW.approval_status) THEN IF NEW.expires_at IS NOT NULL AND NEW.expires_at <= now() THEN RAISE EXCEPTION 'Approval expired' USING ERRCODE='42501'; END IF; IF (SELECT count(DISTINCT aa.approver_id) FROM public.action_approvals aa JOIN public.workspace_members wm ON wm.user_id=aa.approver_id AND wm.workspace_id=NEW.workspace_id AND wm.role IN ('admin','approver') WHERE aa.action_id=NEW.id AND aa.workspace_id=NEW.workspace_id AND aa.action_version=NEW.version AND aa.vote IN ('approve','approve_with_conditions')) < NEW.required_approver_count THEN RAISE EXCEPTION 'Insufficient authorized approvals' USING ERRCODE='42501'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER action_approval_floor BEFORE INSERT OR UPDATE ON public.action_proposals FOR EACH ROW EXECUTE FUNCTION public.enforce_action_approval_floor();
CREATE OR REPLACE FUNCTION public.protect_analysis_snapshot() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.analysis_output IS NOT NULL THEN RAISE EXCEPTION 'Analysis snapshots are immutable'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
CREATE TRIGGER immutable_analysis_snapshot BEFORE UPDATE OR DELETE ON public.decision_context_snapshots FOR EACH ROW EXECUTE FUNCTION public.protect_analysis_snapshot();